  // Include existing rows so databases predating the counter and direct imports
  // start after their highest number as well.
  const row = db.select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)))
    .get();
  const counter = db.select().from(issueNumberCounters)
    .where(and(
      orgPredicate(issueNumberCounters.orgId, orgId),
      eq(issueNumberCounters.projectId, projectId),
    )).get();
  const number = Math.max(row?.value ?? 0, counter?.lastNumber ?? 0) + 1;
  rememberIssueNumber(orgId, projectId, number);
  return number;
}

/** Reserve the next number; issued numbers are never reused. */
export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  return getDb().transaction(() => allocateIssueNumber(orgId, projectId));
}

